const List<DocBlock> componentsInventoryBlocks = [
  ParagraphBlock([Span('Regulatory reference and standard guidelines for software supply chain transparency, vulnerability handling, and interoperability under the European Union Cyber Resilience Act (CRA) and international standards. ', italic: true), Span('\n\nThe purpose of this documentation is to outline the legal and technical framework governing Software Bills of Materials (SBOMs) and Vulnerability Exploitability Exchange (VEX). It incorporates key recitals from Regulation (EU) 2024/2847, guidelines from CISA and ENISA, and major technical standards such as CycloneDX and SPDX.')]),
  ParagraphBlock([Span('For purposes of compliance with the Cyber Resilience Act (CRA), manufacturers and providers of products with digital elements are required to identify and document components through structured, machine-readable data formats.')]),
  ParagraphBlock([Span('The official text of the regulation can be accessed at the '), Span('EUR-Lex Official Journal ', href: 'https://eur-lex.europa.eu/eli/reg/2024/2847/oj/eng'), Span('.')]),
  HeadingBlock(2, '§ 1. Software Bill of Materials (SBOM)'),
  ParagraphBlock([Span('1.1', bold: true), Span(' '), Span('Recital 77', bold: true), Span(' — In order to facilitate vulnerability analysis, manufacturers should identify and document components contained in the products with digital elements, including by drawing up an SBOM. An SBOM can provide those who manufacture, purchase, and operate software with information that enhances their understanding of the supply chain, which has multiple benefits, in particular it helps manufacturers and users to track known newly emerged vulnerabilities and cybersecurity risks. It is of particular importance that manufacturers ensure that their products with digital elements do not contain vulnerable components developed by third parties. Manufacturers should not be obliged to make the SBOM public.')]),
  ParagraphBlock([Span('1.2', bold: true), Span(' '), Span('Annex I, Part II of Regulation (EU) 2024/2847 (Cyber Resilience Act)', bold: true), Span(' — The obligation to create an SBOM is found under Vulnerability handling requirements. This part mandates that manufacturers must identify components and draw up a machine-readable SBOM. Under EU-type examination, a notified body examines the technical design, development, and vulnerability handling processes to attest that the product meets essential cybersecurity requirements.')]),
  HeadingBlock(3, 'Subsections & Regulatory References'),
  ParagraphBlock([Span('1.3', bold: true), Span(' '), Span('2026 Minimum Elements for an SBOM:', bold: true), Span(' Guidelines detailing core data fields required for compliance. (References: '), Span('CISA 2026 SBOM Minimum Elements Document ', href: 'https://www.cisa.gov/sites/default/files/2026-07/2026_cisa_sbom_minimum_elements_508c.pdf'), Span(')')]),
  HeadingBlock(3, '1.4 SBOM Minimum Elements, Data Fields: The data that makes up the SBOM document.'),
  HeadingBlock(4, '1.4.1 SBOM Metadata'),
  ParagraphBlock([Span('SBOM Metadata elements capture information about the SBOM document itself. The data supports SBOM management; SBOM analysis tools leverage these data fields to improve usability of the SBOM data.')]),
  ParagraphBlock([Span('1.4.1.1', bold: true), Span(' '), Span('SBOM Author:', bold: true), Span(' The name of the entity that creates the SBOM data for the target component. Captures the entity operating the tool to generate the SBOM, not the tool itself. Uses full names without acronyms.')]),
  ParagraphBlock([Span('1.4.1.2', bold: true), Span(' '), Span('SBOM Author Signature:', bold: true), Span(' A digital signature attributable to the SBOM author providing assurance that information was not modified after signature generation. Uses secure algorithms recommended by authorities such as NIST, ISO/IEC 14888-4:2024, or ENISA. (Reference: '), Span('NIST Digital Signatures', href: 'https://csrc.nist.gov/Projects/Digital-Signatures'), Span(')')]),
  ParagraphBlock([Span('SBOM Data Format Name:', bold: true), Span(' The name of the data format used to represent the SBOM data (e.g., CycloneDX, SPDX).')]),
  ParagraphBlock([Span('1.4.1.3', bold: true), Span(' '), Span('SBOM Data Format Version:', bold: true), Span(' Identifier designated by the SBOM data format to specify the version of the data format. Deprecated versions should not be used.')]),
  ParagraphBlock([Span('1.4.1.4', bold: true), Span(' '), Span('SBOM Generation Context:', bold: true), Span(' The relative software lifecycle phase and data available at the time the SBOM author generated the SBOM (e.g., "before build," "build," "after build").')]),
  ParagraphBlock([Span('1.4.1.5', bold: true), Span(' '), Span('SBOM Timestamp:', bold: true), Span(' Record of the date and time of the most recent update to the SBOM data adhering to '), Span('RFC 9557', href: 'https://www.rfc-editor.org/info/rfc9557'), Span('.')]),
  ParagraphBlock([Span('1.4.1.6', bold: true), Span(' '), Span('SBOM Tool Name:', bold: true), Span(' The name of the software tool used by the SBOM author to generate or amend the SBOM.')]),
  ParagraphBlock([Span('1.4.1.7', bold: true), Span(' '), Span('SBOM Tool Version:', bold: true), Span(' Identifier for the version of the tool identified in the SBOM Tool Name element.')]),
  ParagraphBlock([Span('1.4.1.8', bold: true), Span(' '), Span('SBOM Version:', bold: true), Span(' Identifier designated by the SBOM author to specify a change in the SBOM document from a previously identified version. May use Semantic Versioning (see '), Span('Semantic Versioning 2.0.0', href: 'https://semver.org/spec/v2.0.0.html'), Span(') or unique identifiers conforming to standards like '), Span('RFC 9562', href: 'https://www.rfc-editor.org/info/rfc9562'), Span('.')]),
  HeadingBlock(4, '1.4.2 Component Data'),
  ParagraphBlock([Span('Component Data elements capture information about the target component and all enumerated subcomponents, enabling better informed risk management decisions.')]),
  ParagraphBlock([Span('1.4.2.1', bold: true), Span(' '), Span('Component Producer:', bold: true), Span(' The name of an entity that creates, defines, and identifies components. (Note: Not to be confused with EU software "manufacturer" under Article 3 of '), Span('Regulation (EU) 2024/2847', href: 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=OJ:L_202402847'), Span(').')]),
  ParagraphBlock([Span('1.4.2.2', bold: true), Span(' '), Span('Component Dependency Relationship:', bold: true), Span(' The relationship between two components, where one component is necessary for the operation of the other.')]),
  ParagraphBlock([Span('1.4.2.3', bold: true), Span(' '), Span('Component Hash Value & Algorithm:', bold: true), Span(' Cryptographic hash output and algorithm used to validate the integrity of the target component artifact.')]),
  ParagraphBlock([Span('1.4.2.4', bold: true), Span(' '), Span('Component Identifiers:', bold: true), Span(' Identifiers used to identify a component or serve as a look-up key, using standard formats such as '), Span('NIST CPE', href: 'https://nvd.nist.gov/products/cpe'), Span(', '), Span('ECMA-427 PURL', href: 'https://ecmainternational.org/publications-and-standards/standards/ecma-427/'), Span(', '), Span('OmniBOR v0.1', href: 'https://omnibor.io/spec/v0.1/'), Span(', and '), Span('SWHID v1.2', href: 'https://www.swhid.org/specification/v1.2/'), Span('.')]),
  ParagraphBlock([Span('1.4.2.5', bold: true), Span(' '), Span('Component License:', bold: true), Span(' Identifier(s) for the license(s) under which the software component is available, leveraging the '), Span('SPDX License List', href: 'https://spdx.org/licenses/'), Span('.')]),
  ParagraphBlock([Span('1.4.2.6', bold: true), Span(' '), Span('Component Name & Version:', bold: true), Span(' Human-readable name and version assigned by the component producer to identify the specific code delivery.')]),
  ParagraphBlock([Span('1.4.2.7', bold: true), Span(' '), Span('CISA SBOM Types:', bold: true), Span(' Framework defining the six types of SBOMs across the Software Development Life Cycle (SDLC). ('), Span(' CISA SBOM Types Document ', href: 'https://www.cisa.gov/sites/default/files/2023-04/sbom-types-document-508c.pdf'), Span(')')]),
  TableBlock(caption: 'Table 1: SBOM Type Definition and Composition', head: ['SBOM Type', 'Definition', 'Data Description'], rows: [[[Span('Design', bold: true)], [Span('SBOM of intended, planned software project or product with included components (some of which may not yet exist) for a new software artifact.')], [Span('Typically derived from a design specification, RFP, or initial concept.')]], [[Span('Source', bold: true)], [Span('SBOM created directly from the development environment, source files, and included dependencies used to build a product artifact.')], [Span('Typically generated from software composition analysis (SCA) tooling, with manual clarifications.')]], [[Span('Build', bold: true)], [Span('SBOM generated as part of the process of building the software to create a releasable artifact (e.g., executable or package) from data such as source files, dependencies, built components, build process ephemeral data, and other SBOMs.')], [Span('Typically generated as part of a build process. May consist of integrated intermediate Build and Source SBOMs for a final release artifact SBOM.')]], [[Span('Analyzed', bold: true)], [Span('SBOM generated through analysis of artifacts (e.g., executables, packages, containers, and virtual machine images) after its build. Such analysis generally requires a variety of heuristics. In some contexts, this may also be referred to as a “3rd party” SBOM.')], [Span('Typically generated through analysis of artifacts by 3rd party tooling.')]], [[Span('Deployed', bold: true)], [Span('SBOM provides an inventory of software that is present on a system. This may be an assembly of other SBOMs that combines analysis of configuration options, and examination of execution behavior in a (potentially simulated) deployment environment.')], [Span('Typically generated by recording the SBOMs and configuration information of artifacts that have been installed on systems.')]]]),
  ParagraphBlock([Span('Securing the Software Supply Chain (2024):', bold: true), Span(' Recommended practices for software bill of materials consumption. ('), Span(' CISA 2024 Consumption Practices ', href: 'https://www.cisa.gov/sites/default/files/2024-08/SECURING_THE_SOFTWARE_SUPPLY_CHAIN_RECOMMENDED_PRACTICES_FOR_SOFTWARE_BILL_OF_MATERIALS_CONSUMPTION-508.pdf'), Span(')')]),
  ParagraphBlock([Span('ENISA Technical Advisory (October 22, 2026):', bold: true), Span(' Practical guidance on the implementation of SBOM requirements under European cybersecurity frameworks. ('), Span(' ENISA Advisory v1.10 ', href: 'https://www.enisa.europa.eu/sites/default/files/2026-10/ENISA%20Technical%20Advisory%20-%20Software%20Bill%20of%20Materials%20-%20v1.10.pdf'), Span(')')]),
  RuleBlock(),
  HeadingBlock(2, '§ 2. Vulnerability Exploitability Exchange (VEX)'),
  ParagraphBlock([Span('The VEX document provides the exploitability status for vulnerabilities associated with component composition identified by the SBOM.')]),
  HeadingBlock(3, 'Subsections & Regulatory References'),
  ParagraphBlock([Span('2.1', bold: true), Span(' '), Span('NTIA Summary:', bold: true), Span(' Foundational overview of VEX principles and objectives. ('), Span(' NTIA VEX One-Page Summary ', href: 'https://www.ntia.gov/files/ntia/publications/vex_one-page_summary.pdf'), Span(')')]),
  ParagraphBlock([Span('2.2', bold: true), Span(' '), Span('CISA 2023 Minimum Requirements for VEX:', bold: true), Span(' Specifies the minimum data elements required to create a valid Vulnerability Exploitability eXchange document. ('), Span(' CISA Minimum Requirements for VEX ', href: 'https://www.cisa.gov/sites/default/files/2023-04/minimum-requirements-for-vex-508c.pdf'), Span(')')]),
