  ParagraphBlock([Span('3.3', bold: true), Span(' '), Span('OWASP Authoritative Guide:', bold: true), Span(' Comprehensive implementation guide for CycloneDX. ('), Span(' OWASP CycloneDX Guide ', href: 'https://cyclonedx.org/guides/OWASP_CycloneDX-Authoritative-Guide-to-SBOM-en.pdf'), Span(')')]),
  ParagraphBlock([Span('3.4', bold: true), Span(' '), Span('The CycloneDX Object Model Specification Overview:', bold: true), Span(' Core structural layout and schema details. ('), Span(' CycloneDX Overview ', href: 'https://cyclonedx.org/specification/overview/'), Span(')')]),
  ParagraphBlock([Span('3.4.1', bold: true), Span(' '), Span('The CycloneDX Object Model.', bold: true), Span(' The CycloneDX object model is a structured framework for representing information relevant for software and system transparency. Designed for clarity, precision, and extensibility, it organizes complex supply chain data into a well-defined schema that is both machine-readable and human-friendly. This model forms the backbone of CycloneDX’s ability to support diverse use cases ranging from vulnerability management and license compliance to cryptographic transparency and operational assurance.')]),
  ImageBlock('Object Model Overview', 'https://cyclonedx.org/images/object-model/CycloneDX-Object-Type-Overview.svg'),
  ParagraphBlock([Span('3.4.2', bold: true), Span(' '), Span('BOM Metadata.', bold: true), Span(' BOM metadata includes the supplier, manufacturer, and target component for which the BOM describes. It also includes the tools used to create the BOM, and license information for the BOM document itself.')]),
  ImageBlock('BOM Metadata', 'https://cyclonedx.org/images/object-model/Metadata.svg'),
  ParagraphBlock([Span('3.4.3', bold: true), Span(' '), Span('Components.', bold: true), Span(' Components describe the complete inventory of first-party and third-party components. The specification can represent software, hardware devices, machine learning models, source code, and configurations, along with the manufacturer information, license and copyright details, and complete pedigree and provenance for every component.')]),
  ImageBlock('Components', 'https://cyclonedx.org/images/object-model/Components.svg'),
  ParagraphBlock([Span('3.4.4', bold: true), Span(' '), Span('Services.', bold: true), Span(' Services represent external APIs that the software may call. They describe endpoint URIs, authentication requirements, and trust boundary traversals. The data flow between software and services can also be described, including the data classifications and the flow direction of each type.')]),
  ImageBlock('Services', 'https://cyclonedx.org/images/object-model/Services.svg'),
  ParagraphBlock([Span('3.4.5', bold: true), Span(' '), Span('Dependencies.', bold: true), Span(' CycloneDX provides the ability to describe components and their dependency on other components. The dependency graph is capable of representing both direct and transitive relationships. Components that depend on services can be represented in the dependency graph, and services that depend on other services can be represented as well.')]),
  ImageBlock('Dependencies', 'https://cyclonedx.org/images/object-model/Dependencies.svg'),
  ParagraphBlock([Span('3.4.6', bold: true), Span(' '), Span('Compositions.', bold: true), Span(' Compositions describe constituent parts (including components, services, and dependency relationships) and their completeness. The aggregate of each composition can be described as complete, incomplete, incomplete first-party only, incomplete third-party only, or unknown.')]),
  ImageBlock('Compositions', 'https://cyclonedx.org/images/object-model/Compositions.svg'),
  ParagraphBlock([Span('3.4.7', bold: true), Span(' '), Span('Vulnerabilities.', bold: true), Span(' Known vulnerabilities inherited from the use of third-party and open-source software and the exploitability of the vulnerabilities can be communicated with CycloneDX. Previously unknown vulnerabilities affecting both components and services may also be disclosed using CycloneDX, making it ideal for both vulnerability disclosure and VEX use cases.')]),
  ImageBlock('Vulnerabilities', 'https://cyclonedx.org/images/object-model/Vulnerabilities.svg'),
  ParagraphBlock([Span('3.4.8', bold: true), Span(' '), Span('Formulation.', bold: true), Span(' Formulation describes how something was manufactured or deployed. CycloneDX achieves this through the support of multiple formulas, workflows, tasks, and steps, which represent the declared formulation for reproduction along with the observed formula describing the actions which transpired in the manufacturing process.')]),
  ImageBlock('Formulation', 'https://cyclonedx.org/images/object-model/Formulation.svg'),
  ParagraphBlock([Span('3.4.9', bold: true), Span(' '), Span('Annotations.', bold: true), Span(' Annotations contain comments, notes, explanations, or similar textual content which provide additional context to the object(s) being annotated. They are often automatically added to a BOM via a tool or as a result of manual review by individuals or organizations. Annotations can be independently signed and verified using digital signatures.')]),
  ImageBlock('Annotations', 'https://cyclonedx.org/images/object-model/Annotations.svg'),
  ParagraphBlock([Span('3.4.10', bold: true), Span(' '), Span('Definitions.', bold: true), Span(' Standards, requirements, levels, and all supporting documentation are defined here. CycloneDX provides a general-purpose, machine-readable way to define virtually any type of standard. Security standards such as OWASP ASVS, MASVS, SCVS, and SAMM are available in CycloneDX format. Standards from other bodies are available as well. Additionally, organizations can create internal standards and represent them in CycloneDX.')]),
  ImageBlock('Definitions', 'https://cyclonedx.org/images/object-model/Definitions.svg'),
  ParagraphBlock([Span('3.4.11', bold: true), Span(' '), Span('Declarations.', bold: true), Span(' Declarations describe the conformance to standards. Each declaration may include attestations, claims, counter-claims, evidence, counter-evidence, along with conformance and confidence. Signatories can also be declared and supports both digital and analog signatures. Declarations provide the basis for "compliance-as-code".')]),
  ImageBlock('Declarations', 'https://cyclonedx.org/images/object-model/Declarations.svg'),
  ParagraphBlock([Span('3.4.12', bold: true), Span(' '), Span('Citations.', bold: true), Span(' Citations identify who contributed specific pieces of information to a CycloneDX BOM and when that contribution was made. They connect data in the BOM to its source, whether that’s a tool, person, organization, or process. This traceability adds transparency, helping others assess the reliability and origin of the data. Citations are essential when multiple sources contribute to the same BOM.')]),
  ImageBlock('Citations', 'https://cyclonedx.org/images/object-model/Citations.svg'),
  ParagraphBlock([Span('3.4.13', bold: true), Span(' '), Span('Extensions.', bold: true), Span(' Multiple extension points exist throughout the CycloneDX object model, allowing fast prototyping of new capabilities and support for specialized and future use cases. The CycloneDX project maintains extensions that are beneficial to the larger community. The project encourages community participation and the development of extensions that target specialized or industry-specific use cases.')]),
  ImageBlock('Extensions', 'https://cyclonedx.org/images/object-model/Extensions.svg'),
  ParagraphBlock([Span('3.4.14', bold: true), Span(' '), Span('Media Types & Serialization Formats.', bold: true), Span(' CycloneDX can be represented in JSON, XML, and Protocol Buffers (protobuf) and has corresponding schemas for each. The following media types are officially registered with IANA:')]),
